let queryCount = 0;

function listOrdersWithCustomerJoined(db) {
  queryCount++;
  const customerById = new Map(db.customers.map((c) => [c.id, c]));
  return db.orders.map((order) => ({
    ...order,
    customerName: customerById.get(order.customerId).name,
  }));
}

